import {fleetRecords,fleetTelemetry,VEHICLE_TYPES,AUTHORIZATION_STATES,BEACON_FIRMWARE} from './fleet.js';
import {escapeHTML as esc} from './operations-ui.js';
const badge=status=>`<span class="fleet-state ${esc(status)}">${esc(AUTHORIZATION_STATES[status]||status)}</span>`;
const label=d=>d.setup_state==='simulated_verified'?'Simulator checked':'Setup pending';
const siteName=j=>(j?.name||'').replace(/^\d+ · /,'');

export function fleetHTML(project,frame,{query='',filter='all',selectedId=null,readOnly=false}={}){
 const all=fleetTelemetry(project,frame),q=query.toLowerCase().trim(),rows=all.filter(v=>(filter==='all'||v.vehicle_type===filter)&&(!q||[v.id,v.call_sign,v.agency,v.registration,v.beacon_id].some(s=>String(s||'').toLowerCase().includes(q)))),selected=all.find(v=>v.id===selectedId)||all[0];
 return `<div class="title-row"><div><span class="eyebrow">T.E.A.M. / EMERGENCY VEHICLES</span><h1>Emergency fleet</h1><p class="subtitle">Register a vehicle, assign its beacon, then prepare the installation.</p></div><button class="button dark" data-action="vehicle-new" ${readOnly?'disabled':''}>＋ Register vehicle</button></div><div class="fleet-summary"><span><b>${all.length}</b> registered</span><span><b>${all.filter(v=>v.authorization_status==='approved').length}</b> approved for priority</span><span><b>${all.filter(v=>v.authorization_status==='pending').length}</b> awaiting approval</span></div><div class="fleet-layout"><section class="panel fleet-register"><div class="fleet-search-bar"><label class="fleet-search"><span>Search vehicles</span><input id="fleet-search" type="search" placeholder="Call sign, agency, plate or beacon" value="${esc(query)}"></label><label class="fleet-filter"><span>Vehicle type</span><select id="fleet-filter"><option value="all">All types</option>${Object.entries(VEHICLE_TYPES).map(([id,t])=>`<option value="${id}" ${filter===id?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div><div id="fleet-table">${fleetTableHTML(rows,selected?.id)}</div><div class="table-note">Records are saved in this browser workspace and included in the installation project export.</div></section><div id="fleet-selected">${selected?vehicleDetailHTML(project,selected,readOnly):'<section class="panel"><div class="empty">Register your first vehicle to assign a beacon.</div></section>'}</div></div>`;
}
export function fleetTableHTML(rows,selectedId){return rows.length?`<div class="table-wrap"><table class="fleet-table"><thead><tr><th>VEHICLE</th><th>AGENCY</th><th>BEACON</th><th>PRIORITY</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr class="${v.id===selectedId?'selected':''}"><td><strong>${esc(v.call_sign)}</strong><small>${esc(VEHICLE_TYPES[v.vehicle_type])}${v.registration?' · '+esc(v.registration):''}${v.demo?' · example':''}</small></td><td>${esc(v.agency)}</td><td><span class="mono">${esc(v.beacon_id)}</span><small>${v.track?esc(v.track.status):'Awaiting telemetry'}</small></td><td>${badge(v.authorization_status)}</td><td><button class="button small" data-vehicle-select="${esc(v.id)}" aria-label="View ${esc(v.call_sign)}">Details</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No vehicles match this view.</div>';}
export function vehicleDetailHTML(project,v,readOnly=false){return `<section class="panel vehicle-detail"><div class="panel-head"><div><span class="eyebrow">VEHICLE RECORD</span><h2>${esc(v.call_sign)}</h2></div>${badge(v.authorization_status)}</div><div class="panel-body"><div class="vehicle-type-symbol">${v.vehicle_type==='ambulance'?'✚':v.vehicle_type==='fire'?'♨':'◇'}</div><dl class="vehicle-facts"><dt>Type</dt><dd>${esc(VEHICLE_TYPES[v.vehicle_type])}</dd><dt>Agency</dt><dd>${esc(v.agency)}</dd><dt>Plate / registration</dt><dd>${esc(v.registration||'Not recorded')}</dd><dt>Vehicle ID</dt><dd class="mono">${esc(v.id)}</dd><dt>Beacon ID</dt><dd class="mono">${esc(v.beacon_id)}</dd><dt>Hardware UID</dt><dd class="mono">${esc(v.hardware_uid||'Not recorded')}</dd><dt>Beacon setup</dt><dd>${label(v)}</dd><dt>Last received</dt><dd>${v.track?`${v.track.age_s.toFixed(0)} s ago · ${esc(v.track.status)}`:'Awaiting telemetry'}</dd><dt>Approval reference</dt><dd>${esc(v.authorization_reference||'Pending agency approval')}</dd></dl><div class="vehicle-actions"><button class="button dark" data-vehicle-install="${esc(v.id)}" ${readOnly?'disabled':''}>Install beacon ↗</button><button class="button" data-vehicle-edit="${esc(v.id)}" ${readOnly?'disabled':''}>Edit registration</button></div>${v.authorization_status!=='approved'?'<p class="hint">Priority is inactive until the registration is approved.</p>':''}<details class="vehicle-technical"><summary>Beacon configuration</summary><p>Shared firmware: <span class="mono">${BEACON_FIRMWARE}</span></p><p>Each unit receives its own vehicle and beacon IDs. Protected identity credentials are enrolled separately from this workspace.</p><button class="button small" data-vehicle-test="${esc(v.id)}" ${readOnly||v.authorization_status!=='approved'?'disabled':''}>Test approach in simulator</button></details></div></section>`;}

export function vehicleFormHTML(project,{id=null,newId=''}={}){
 const v=fleetRecords(project).find(v=>v.id===id)||{id:newId,call_sign:'',agency:'',vehicle_type:'ambulance',registration:'',beacon_id:'BCN-'+newId.replace(/^VEH-/,''),hardware_uid:'',home_site_id:project.intersections[0].id,authorization_status:'pending',authorization_reference:''};
 return `<h2>${id?'Edit registration':'Register an emergency vehicle'}</h2><form id="vehicle-form" data-edit-id="${esc(id||'')}"><input name="id" type="hidden" value="${esc(v.id)}"><div class="two-fields"><div class="field"><label for="vehicle-call-sign">Call sign / unit name</label><input id="vehicle-call-sign" name="call_sign" required maxlength="80" value="${esc(v.call_sign)}" placeholder="e.g. Rescue 01"></div><div class="field"><label for="vehicle-type">Vehicle type</label><select id="vehicle-type" name="vehicle_type">${Object.entries(VEHICLE_TYPES).map(([key,label])=>`<option value="${key}" ${v.vehicle_type===key?'selected':''}>${esc(label)}</option>`).join('')}</select></div></div><div class="two-fields"><div class="field"><label for="vehicle-agency">Operating agency</label><input id="vehicle-agency" name="agency" required maxlength="120" value="${esc(v.agency)}" placeholder="Agency / hospital / response unit"></div><div class="field"><label for="vehicle-registration">Plate / registration (optional)</label><input id="vehicle-registration" name="registration" maxlength="32" value="${esc(v.registration)}"></div></div><div class="two-fields"><div class="field"><label for="vehicle-beacon-id">Beacon ID</label><input id="vehicle-beacon-id" name="beacon_id" required maxlength="64" pattern="[A-Za-z0-9_-]{1,64}" value="${esc(v.beacon_id)}"></div><div class="field"><label for="vehicle-hardware-uid">Hardware UID (if available)</label><input id="vehicle-hardware-uid" name="hardware_uid" maxlength="80" value="${esc(v.hardware_uid)}" placeholder="Read from the physical unit"></div></div><div class="field"><label for="vehicle-home-site">Home service site</label><select id="vehicle-home-site" name="home_site_id">${project.intersections.map(j=>`<option value="${esc(j.id)}" ${v.home_site_id===j.id?'selected':''}>${esc(siteName(j))}</option>`).join('')}</select><small>Administrative assignment. The vehicle may approach any configured intersection.</small></div><div class="two-fields"><div class="field"><label for="vehicle-authorization">Priority authorization</label><select id="vehicle-authorization" name="authorization_status">${Object.entries(AUTHORIZATION_STATES).map(([key,label])=>`<option value="${key}" ${v.authorization_status===key?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="field"><label for="vehicle-approval-reference">Approval reference</label><input id="vehicle-approval-reference" name="authorization_reference" maxlength="160" ${v.authorization_status==='approved'?'required':''} value="${esc(v.authorization_reference)}" placeholder="Required when approved"></div></div><p class="hint">Registration is saved locally. This authorization setting controls the simulator; live agency approval and protected beacon enrollment are separate integrations.</p><p id="vehicle-form-error" class="form-error" role="alert"></p><button type="submit" class="button dark">${id?'Save changes':'Register vehicle'}</button></form>`;
}

export function beaconInstallationHTML(project,{vehicleId,config,log='',percent=0,busy=false}={}){
 const vehicles=fleetRecords(project),v=vehicles.find(v=>v.id===vehicleId)||vehicles[0],d=v&&project.devices.find(d=>d.id===v.beacon_id);
 return `<div class="title-row"><div><span class="eyebrow">INSTALLATION / VEHICLE BEACONS</span><h1>Prepare a vehicle beacon</h1><p class="subtitle">Choose the registered vehicle, prepare its configuration, then verify the device setup.</p></div><button class="button" data-view="vehicles">Emergency fleet ↗</button></div><div class="installation-mode-switch" role="group" aria-label="Installation type"><button class="button" data-action="install-area-mode">Area planner</button><button class="button" data-action="install-road-mode">Configured sites</button><button class="button dark" data-action="install-beacon-mode" aria-pressed="true">Vehicle beacons</button></div>${!v?'<section class="panel"><div class="empty">Register a vehicle in Emergency fleet first.</div></section>':`<div class="beacon-install-grid"><section class="panel"><div class="panel-head"><h2>Vehicle & beacon</h2>${badge(v.authorization_status)}</div><div class="panel-body"><div class="field"><label for="beacon-install-vehicle">Registered vehicle</label><select id="beacon-install-vehicle">${vehicles.map(x=>`<option value="${esc(x.id)}" ${x.id===v.id?'selected':''}>${esc(x.call_sign)} · ${esc(x.beacon_id)}</option>`).join('')}</select></div><dl class="vehicle-facts"><dt>Agency</dt><dd>${esc(v.agency)}</dd><dt>Vehicle ID</dt><dd class="mono">${esc(v.id)}</dd><dt>Beacon ID</dt><dd class="mono">${esc(v.beacon_id)}</dd><dt>Hardware UID</dt><dd>${esc(v.hardware_uid||'Not recorded')}</dd><dt>Firmware build</dt><dd class="mono">${BEACON_FIRMWARE}</dd><dt>Priority</dt><dd>${v.authorization_status==='approved'?'Enabled in simulator':'Inactive · awaiting authorization'}</dd></dl><div class="vehicle-actions"><button class="button dark" data-action="device-json">Download configuration</button><button class="button" data-action="commission" ${busy?'disabled':''}>${busy?'Verifying…':'Verify in simulator'}</button></div><button class="subtle-link" data-vehicle-edit="${esc(v.id)}">Edit vehicle registration ↗</button></div></section><section class="panel"><div class="panel-head"><h2>Setup verification</h2><span class="badge ${d?.commissioning?.state==='simulated_verified'?'blue':'gray'}">${d?.commissioning?.state==='simulated_verified'?'SIMULATOR CHECKED':'NOT VERIFIED'}</span></div><div class="panel-body"><ol class="beacon-setup-steps"><li><b>Registration linked</b><span>${esc(v.call_sign)} → ${esc(v.beacon_id)}</span></li><li><b>Shared firmware, unique configuration</b><span>The vehicle identity changes per unit; the firmware build stays the same.</span></li><li><b>Read back the configuration</b><span>The simulator checks saved identity and configuration. Physical USB / radio verification is performed separately.</span></li></ol><div class="progress-track"><i style="width:${percent}%"></i></div>${log?`<div class="commission-log" aria-live="polite">${esc(log)}</div>`:'<p class="hint">Choose Verify in simulator to check the saved configuration.</p>'}</div></section></div><details class="operations-diagnostics"><summary><span>Configuration details</span><span>Public profile · no protected credentials</span></summary><pre class="code">${esc(JSON.stringify(config||{},null,2))}</pre></details>`}`;
}
